    +'<div class="field"><label>Date and time</label><input name="when" type="datetime-local" required value="'+when+'"></div><div class="field"><label>Product *</label><select name="product" required>'+products+'</select></div>'
    +'<div class="field"><label>Weight · g *</label><input name="weight" type="number" min=".001" step=".001" required value="'+(x?.weight||'')+'" oninput="calcSale(this.form)"></div><div class="field"><label>Pieces *</label><input name="pieces" type="number" min="1" step="1" required value="'+(x?.pieces||1)+'" oninput="calcSale(this.form)"></div>'
    +'<div class="field"><label>Purity · % *</label><select name="purity" required onchange="calcSale(this.form)">'+purities+'</select></div><div class="field"><label>Wastage · %</label><input name="wastage" type="number" min="0" step=".01" value="'+(x?.wastage||0)+'" oninput="calcSale(this.form)"></div>'
