window.refreshSalePrice=function(form){
  if(!form||form.elements.accountType.value!=='customer')return;
  const purity=n(form.elements.purity.value),perGram=v2RateForPurity(purity),base=purity>0?perGram*24/purity:0;
  form.elements.rate24.value=base.toFixed(4);if(form.elements.ratePerGram)form.elements.ratePerGram.value=perGram.toFixed(4);
  const label=form.querySelector('#salePurityRateLabel');if(label)label.textContent=perGram>0?rateMoney(perGram)+' / g · '+purity+'K from Rate Book':'Set rates in Rate Book';
  calcSale(form);
};
window.calcHallmarkCharge=function(form){if(!form)return;const total=Math.round(n(form.elements.pieces?.value)*n(form.elements.hallmarkChargePerPiece?.value)*100)/100,node=form.querySelector('#partyHallmarkTotal');if(node)node.textContent=v2Money(total)};
window.calcSale=function(form){
  if(!form)return;const customer=form.elements.accountType.value==='customer',rows=customer?exchangeRows(form):[],exchangeAmount=rows.reduce((a,x)=>a+x.amount,0),exchangePure=rows.reduce((a,x)=>a+x.pureGrams,0),discount=customer?n(form.elements.discount?.value):n(form.elements.partyDiscountGrams?.value);
  const totalLabel=form.querySelector('#exchangeAmountTotal');if(totalLabel)totalLabel.textContent=rateMoney(exchangeAmount);
  const pureLabel=form.querySelector('#exchangePureTotal');if(pureLabel)pureLabel.textContent=fmt(exchangePure)+' g';
  if(customer){
    const totals=customerSaleTotals({weight:form.elements.weight.value,purity:form.elements.purity.value,rate24:form.elements.rate24.value,wastage:form.elements.wastage.value,pieces:form.elements.pieces.value,makingPerPiece:form.elements.makingPerPiece.value,discount,gstEnabled:!!form.elements.gstEnabled?.checked,gstRate:n(form.elements.gstRate?.value),gstMode:form.elements.gstMode?.value});
    const net=totals.final-exchangeAmount,collected=n(form.elements.collectedAmount?.value),due=net-collected,set=(id,value)=>{const node=form.querySelector('#'+id);if(node)node.textContent=value};
    set('saleGoldAmount',rateMoney(totals.goldAmount));set('saleWastageAmount',rateMoney(totals.wastageAmount));set('saleMakingAmount',rateMoney(totals.makingTotal));set('saleSubtotal',rateMoney(totals.subtotal));set('saleAfterDiscount',rateMoney(totals.final));set('saleExchangeAmount',rateMoney(exchangeAmount));set('saleCollectedAmount',rateMoney(collected));set('saleBalanceAmount',rateMoney(Math.abs(due)));set('saleBalanceLabel',due<0?'Customer credit':due===0?'Balance settled':'Balance due');
    if(form.elements.amount)form.elements.amount.value=net.toFixed(2);
    const purityLabel=form.querySelector('#salePurityRateLabel');if(purityLabel)purityLabel.textContent=rateMoney(totals.purityRate)+' / g · '+form.elements.purity.value+'K from Rate Book';
  }else{
    const gross=n(form.elements.weight.value)*(n(form.elements.purity.value)+n(form.elements.wastage.value))/100,net=gross-discount-exchangePure,hallmark=Math.round(n(form.elements.pieces?.value)*n(form.elements.hallmarkChargePerPiece?.value)*100)/100,set=(id,value)=>{const node=form.querySelector('#'+id);if(node)node.textContent=value};
    set('partyGrossSale',fmt(gross)+' g');set('partyDiscountTotal',fmt(discount)+' g');set('partyExchangePure',fmt(exchangePure)+' g');set('partyNetLabel',net<0?'Gold balance in party favour':'Balance to collect');set('partyNetTotal',fmt(Math.abs(net))+' g');set('partyHallmarkTotal',v2Money(hallmark));
  }
};
