function v2OldGoldWeight(sale){return (sale.oldGoldItems||[]).reduce((sum,item)=>sum+n(item.weight),0)}
function v2OldGoldDetails(sale){return (sale.oldGoldItems||[]).map(item=>esc(item.product||'Old jewellery')+' '+fmt(item.weight)+'g @ '+n(item.testingPurity).toFixed(1)+'%').join(', ')||'—'}
function v2SalePurchase(item){return item.saleAmount!==undefined&&item.saleAmount!==null?n(item.saleAmount):n(item.amount)+n(item.exchangeAmount)}
function v2LedgerSummary(entity,type,rows,closing){
  const sales=db.sales.filter(item=>ownerType(item)===type&&item.partyId===entity.id&&inPeriod(item.when)),payments=db.payments.filter(item=>ownerType(item)===type&&item.partyId===entity.id&&inPeriod(item.when));
  const money=type==='customer',gross=sales.reduce((sum,item)=>sum+n(item.weight),0),pure=sales.reduce((sum,item)=>sum+v2RetailPureWeight(item),0),purchase=sales.reduce((sum,item)=>sum+v2SalePurchase(item),0),oldWeight=sales.reduce((sum,item)=>sum+v2OldGoldWeight(item),0),oldValue=sales.reduce((sum,item)=>sum+n(item.exchangeAmount),0),collected=sales.reduce((sum,item)=>sum+saleCollectionValue(item),0),otherPaid=payments.reduce((sum,item)=>sum+(item.retailKind==='return'?0:accountPaymentValue(item)),0),paid=collected+otherPaid;
  const summary=money?'<div class="cards v2-ledger-stats">'+card('GOLD TAKEN',fmt(gross)+' g')+card('PURE GOLD EQUIVALENT',fmt(pure)+' g')+card('PURCHASE VALUE',v2Money(purchase))+card('OLD GOLD GIVEN',fmt(oldWeight)+' g · '+v2Money(oldValue))+card('TOTAL AMOUNT PAID',v2Money(paid))+card('AMOUNT PENDING',v2Money(closing))+'</div>':'<div class="cards v2-ledger-stats">'+card('GOLD TAKEN',fmt(gross)+' g')+card('PURE PAYABLE',fmt(sales.reduce((sum,item)=>sum+accountSaleValue(item),0))+' g')+card('PAYMENTS CREDITED',fmt(-rows.filter(row=>row.type==='Payment').reduce((sum,row)=>sum+row.amount,0))+' g')+card('BALANCE PENDING',fmt(closing)+' g')+'</div>';
  return summary;
}
window.ledgerView=function(){const type=workspaceMode==='retail'?'customer':'party';ledgerType=type;return type==='customer'?ledgerPage('customer'):v2PartyLedgerPage()};
window.customerLedgerView=function(){return ledgerPage('customer')};
window.ledgerPage=function(type){
  const key=type==='customer'?'customer':'party',entity=account(filter[key],type),money=type==='customer',label=money?'customer':'party',accounts=money?db.customers:db.parties,unit=money?'₹':'g';
  if(!entity){const list=accounts.map(item=>{const current=bal(item.id,type);return [esc(item.name),esc(accountCity(item.id,type)||'—'),money?accountOpening(item,type).toFixed(2):fmt(accountOpening(item,type)),money?v2Money(current):fmt(current)+' g','<button onclick="filter.'+key+'=\''+item.id+'\';render()">Open ledger</button>']});return header('Choose a '+label+' to open its complete transaction report.')+'<section class="panel"><h2>'+label.charAt(0).toUpperCase()+label.slice(1)+' ledger filters</h2>'+controls(type)+(list.length?table([money?'Customer':'Party','City',money?'Opening ₹':'Opening g',money?'Current balance':'Current balance g',''],list):'<div class="empty">Register a '+label+' first.</div>')+'</section>'}
  const rows=tx(entity.id,type),opening=accountOpening(entity,type)+openingBefore(entity.id,type);let closing=opening;
  const summaryClosing=rows.reduce((sum,row)=>sum+row.amount,opening);
  const stats=v2LedgerSummary(entity,type,rows,summaryClosing);
  const headings=money?['Date','Entry','Purchase / payment details','Gold taken g','Pure equivalent g','Purchase value ₹','Old gold given','Paid by / method','Amount paid ₹','Bill pending ₹','Running balance ₹']:['Date','Entry','Product / payment type','Gold weight g','Purity / testing','Wastage','Sale debit g','Payment gross / amount','Payment rate / test','Pure credit g','Running balance g'];
  const tableRows=rows.map(row=>{
    closing+=row.amount;
    if(money){
      if(row.type==='Sale'){const purchase=v2SalePurchase(row),billPending=v2BillPending(row),old= row.exchangeAmount?fmt(v2OldGoldWeight(row))+' g · '+v2Money(row.exchangeAmount)+'<br><small>'+v2OldGoldDetails(row)+'</small>':'—',method=saleCollectionValue(row)?esc(row.collectedMethod||'Cash')+(row.collectedReference?' · '+esc(row.collectedReference):''):'—';return [row.when.replace('T',' '),'Sale',esc(row.product)+'<br><small>'+esc(v2RetailPurityText(row))+' · '+esc(row.wastageLabel||n(row.wastage)+'%')+' wastage</small>',fmt(row.weight),fmt(v2RetailPureWeight(row)),v2Money(purchase),old,method,saleCollectionValue(row)?v2Money(saleCollectionValue(row)):'—',v2Money(billPending),v2Money(closing)]}
      if(row.retailKind==='return')return [row.when.replace('T',' '),'Sales return',esc(row.desc),fmt(-n(row.returnWeight)),'—',v2Money(row.amount),'—','Account credit','—','—',v2Money(closing)];
      const method=esc(row.method||row.kind||'Cash'),reference=row.reference||'';return [row.when.replace('T',' '),row.isBillCollection?'Bill collection':row.retailKind?esc(row.kind):'Payment',esc(row.desc||method), '—','—','—','—',method+(reference?' · '+esc(reference):''),v2Money(-row.amount),'—',v2Money(closing)];
    }
    const sale=row.type==='Sale',grossPay=!sale&&row.kind!=='Cash'?fmt(row.weight)+' g':!sale?'₹ '+n(row.amount).toFixed(2):'—',purity=sale?n(row.purity).toFixed(2)+'%':row.kind==='Cash'?'24K ₹ '+n(row.rate).toFixed(2)+'/g':n(row.purity).toFixed(2)+'%',payCredit=sale?'—':fmt(-row.amount)+' g';
    return [row.when.replace('T',' '),sale?'Sale':'Payment',esc(sale?row.product:row.kind)+(sale?'<br><small>'+n(row.wastage)+'% wastage</small>':''),sale?fmt(row.weight):'—',purity,sale?n(row.wastage).toFixed(2)+'%':'—',sale?fmt(row.amount)+' g':'—',grossPay,sale?'—':(row.kind==='Cash'?'₹ '+n(row.rate).toFixed(2)+'/g':n(row.purity).toFixed(2)+'%'),payCredit,fmt(closing)+' g'];
  });
  const actions='<div class="v2-ledger-actions"><button type="button" onclick="viewLedgerPdf(\''+type+'\')">View PDF</button><button type="button" class="primary" onclick="shareLedger(\''+type+'\')">Share</button></div>';
  const openingLabel=money?v2Money(opening):fmt(opening)+' g',closingLabel=money?v2Money(summaryClosing):fmt(summaryClosing)+' g';
  return header((money?'Customer':'Party')+' transaction report · '+(money?'amounts in rupees.':'pure gold balances in grams.'),actions)+'<section class="panel v2-ledger-panel"><div class="v2-ledger-title"><div><h2>'+esc(entity.name)+' · '+(money?'Customer ledger':'Party ledger')+'</h2><span class="muted">'+esc(accountCity(entity.id,type)||'')+'</span></div></div>'+controls(type)+'<div id="ledgerReportArea" class="v2-ledger-report"><div class="v2-ledger-report-head"><div><h2>Goldleaf · '+(money?'Customer':'Party')+' Ledger</h2><p>'+esc(entity.name)+(accountCity(entity.id,type)?' · '+esc(accountCity(entity.id,type)):'')+'</p></div><span>Period opening: <b>'+openingLabel+'</b></span></div>'+stats+table(headings,tableRows)+'<div class="v2-ledger-closing">Closing balance: <b>'+closingLabel+'</b></div></div></section>';
};
window.viewLedgerPdf=function(type){const report=document.getElementById('ledgerReportArea');if(!report)return say('Select an account to view its ledger PDF.');const copy=report.cloneNode(true);copy.querySelector('.v2-ledger-report-head')?.remove();copy.querySelector('.v2-ledger-stats')?.remove();let root=document.getElementById('ledgerPrintRoot');if(!root){root=document.createElement('div');root.id='ledgerPrintRoot';document.body.append(root)}root.innerHTML='<article class="v2-print-ledger"><h2>Goldleaf · '+(type==='customer'?'Customer':'Party')+' Ledger</h2><div>'+copy.innerHTML+'</div></article>';const article=root.querySelector('article'),table=article.querySelector('.table'),closing=article.querySelector('.v2-party-closing')||article.querySelector('.v2-ledger-closing');if(closing){closing.classList.add('v2-print-ending');if(table)table.after(closing)}document.body.classList.add('printing-ledger-report');window.addEventListener('afterprint',()=>document.body.classList.remove('printing-ledger-report'),{once:true});say('In the print preview, choose Save as PDF.');setTimeout(()=>window.print(),80)};
window.shareLedger=async function(type){const key=type==='customer'?'customer':'party',entity=account(filter[key],type);if(!entity)return say('Select an account before sharing its ledger.');const money=type==='customer',rows=tx(entity.id,type),closing=accountOpening(entity,type)+openingBefore(entity.id,type)+rows.reduce((sum,row)=>sum+row.amount,0);let lines=['Goldleaf '+(money?'Customer':'Party')+' Ledger',entity.name,accountCity(entity.id,type)||'',money?'Balance pending: '+v2Money(closing):'Balance pending: '+fmt(closing)+' g','Transactions:'];for(const row of rows){lines.push(row.when.replace('T',' ')+' | '+row.type+' | '+row.desc+' | '+(money?(row.amount<0?'Paid ':'Sale ')+v2Money(Math.abs(row.amount)):fmt(Math.abs(row.amount))+' g'))}const text=lines.filter(Boolean).join('\n');try{if(navigator.share)await navigator.share({title:'Goldleaf ledger · '+entity.name,text,url:location.href});else if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text);say('Ledger report copied. Paste it into the app you want to share with.')}else say(text)}catch(error){if(error?.name!=='AbortError')say('Could not open the share menu. Use View PDF to print or save this report.')}};
function v2PartyAmountPayment(payment){const original=db.payments.find(p=>p.id===payment.id)||payment;return ownerType(original)==='party'&&original.kind==='Cash'&&original.cashPurpose==='hallmark'?n(original.amount):0}
function v2PartyAmountDelta(row){return row.type==='Sale'?v2HallmarkAmount(row):row.type==='Payment'? -v2PartyAmountPayment(row):0}
function v2PartyAmountBefore(id){return db.sales.filter(item=>item.partyId===id&&ownerType(item)==='party'&&beforePeriod(item.when)).reduce((sum,item)=>sum+v2HallmarkAmount(item),0)-db.payments.filter(item=>item.partyId===id&&ownerType(item)==='party'&&beforePeriod(item.when)).reduce((sum,item)=>sum+v2PartyAmountPayment(item),0)}
function v2PartyAmountCurrent(id){return db.sales.filter(item=>item.partyId===id&&ownerType(item)==='party').reduce((sum,item)=>sum+v2HallmarkAmount(item),0)-db.payments.filter(item=>item.partyId===id&&ownerType(item)==='party').reduce((sum,item)=>sum+v2PartyAmountPayment(item),0)}
function v2SignedMoney(value){return value>0?'+'+v2Money(value):value<0?'−'+v2Money(-value):'—'}
function v2PartyLedgerPage(){
  const entity=account(filter.party,'party');
  if(!entity){const records=db.parties.map(item=>{const gold=bal(item.id,'party'),amount=v2PartyAmountCurrent(item.id);return [esc(item.name),esc(accountCity(item.id,'party')||'—'),fmt(accountOpening(item,'party'))+' g',fmt(gold)+' g',v2Money(amount),'<button type="button" onclick="filter.party=\''+item.id+'\';render()">Open ledger</button>']});return header('Party ledger · gold grams and hallmark cash balances are tracked separately.')+'<section class="panel"><h2>Party ledger filters</h2>'+controls('party')+(records.length?table(['Party','City','Opening gold','Gold balance','Hallmark amount balance',''],records):'<div class="empty">Register a party first.</div>')+'</section>'}
  const rows=tx(entity.id,'party'),opening=accountOpening(entity,'party')+openingBefore(entity.id,'party'),amountOpening=v2PartyAmountBefore(entity.id);let closing=opening,amountClosing=amountOpening;
  const summaryClosing=rows.reduce((sum,row)=>sum+row.amount,opening),summaryAmount=rows.reduce((sum,row)=>sum+v2PartyAmountDelta(row),amountOpening);
  const periodSales=db.sales.filter(item=>item.partyId===entity.id&&ownerType(item)==='party'&&inPeriod(item.when)),periodPayments=db.payments.filter(item=>item.partyId===entity.id&&ownerType(item)==='party'&&inPeriod(item.when)),hallmarkBilled=periodSales.reduce((sum,item)=>sum+v2HallmarkAmount(item),0),hallmarkPaid=periodPayments.reduce((sum,item)=>sum+v2PartyAmountPayment(item),0),goldPaid=periodPayments.reduce((sum,item)=>sum+accountPaymentValue(item),0);
  const goldStatus=summaryClosing<0?'Gold credit':'Gold balance',amountStatus=summaryAmount<0?'Amount credit':'Amount balance',goldText=fmt(Math.abs(summaryClosing))+' g',amountText=(summaryAmount<0?'Credit · ':'')+v2Money(Math.abs(summaryAmount));
  const stats='<div class="v2-party-balance-cards"><div class="v2-party-gold-card"><span>'+goldStatus+' · pure</span><b>'+goldText+'</b></div><div class="v2-party-amount-card"><span>'+amountStatus+' · hallmark</span><b>'+amountText+'</b></div></div><div class="cards v2-ledger-stats">'+card('GOLD TAKEN',fmt(periodSales.reduce((sum,item)=>sum+n(item.weight),0))+' g')+card('PURE GOLD PAYABLE',fmt(periodSales.reduce((sum,item)=>sum+accountSaleValue(item),0))+' g')+card('GOLD CREDITED',fmt(goldPaid)+' g')+card('HALLMARK CHARGED',v2Money(hallmarkBilled))+card('HALLMARK CASH PAID',v2Money(hallmarkPaid))+'</div>';
  const headings=['Date','Entry','Product / payment','Gold weight / gross','Purity / testing','Gold debit g','Gold credit g','Cash amount ₹','Hallmark / cash purpose','Hallmark amount ±₹','Gold balance g','Amount balance ₹'];
  const tableRows=rows.map(row=>{closing+=row.amount;amountClosing+=v2PartyAmountDelta(row);const sale=row.type==='Sale';if(sale){const hallmark=row.hallmarkType?esc(row.hallmarkType)+' · '+(row.pieces||1)+' pcs × '+v2Money(row.hallmarkChargePerPiece)+'/pc':'—';return [row.when.replace('T',' '),'Sale',esc(row.product),fmt(row.weight)+' g',n(row.purity).toFixed(2)+'%',fmt(accountSaleValue(row))+' g','—','—',hallmark,v2SignedMoney(v2HallmarkAmount(row)),fmt(closing)+' g',v2Money(amountClosing)]}
    const hallmarkPurpose=row.kind==='Cash'&&row.cashPurpose==='hallmark',purpose=row.kind==='Cash'?(hallmarkPurpose?'Cash → hallmark balance':'Cash → gold balance'):'Metal → gold balance',purity=row.kind==='Cash'?(hallmarkPurpose?'—':'24K · '+v2Money(row.rate)+'/g'):n(row.purity).toFixed(2)+'%';return [row.when.replace('T',' '),'Payment',esc(row.kind),row.kind==='Cash'?'—':fmt(row.weight)+' g',purity,'—',-row.amount>0?fmt(-row.amount)+' g':'—',row.kind==='Cash'?v2Money(row.amount):'—',purpose,hallmarkPurpose?v2SignedMoney(-n(row.amount)):'—',fmt(closing)+' g',v2Money(amountClosing)]});
  const actions='<div class="v2-ledger-actions"><button type="button" onclick="viewLedgerPdf(\'party\')">View PDF</button><button type="button" class="primary" onclick="shareLedger(\'party\')">Share</button></div>',openingText='Gold '+fmt(opening)+' g · Hallmark '+v2Money(amountOpening),goldClosing=summaryClosing<0?'Credit · '+goldText:goldText;
  return header('Party transaction report · gold grams and cash amounts stay separate.',actions)+'<section class="panel v2-ledger-panel"><div class="v2-ledger-title"><div><h2>'+esc(entity.name)+' · Party ledger</h2><span class="muted">'+esc(accountCity(entity.id,'party')||'')+'</span></div></div>'+controls('party')+'<div id="ledgerReportArea" class="v2-ledger-report"><div class="v2-ledger-report-head"><div><h2>Goldleaf · Party Ledger</h2><p>'+esc(entity.name)+(accountCity(entity.id,'party')?' · '+esc(accountCity(entity.id,'party')):'')+'</p></div><span>Period opening: <b>'+openingText+'</b></span></div>'+stats+table(headings,tableRows)+'<div class="v2-party-closing"><span>Closing gold balance <b>'+goldClosing+'</b></span><span>Closing hallmark amount balance <b>'+amountText+'</b></span></div></div></section>';
}
window.ledgerView=function(){const type=workspaceMode==='retail'?'customer':'party';ledgerType=type;return type==='customer'?ledgerPage('customer'):v2PartyLedgerPage()};
window.summaryView=function(){const type=workspaceMode==='retail'?'customer':'party';summaryType=type;return summaryPage(type)};
const V2_CLOUD_PENDING_KEY='goldleaf-ledger-v1-cloud-pending';
let v2CloudBusy=false,v2CloudQueuedPush=false,v2CloudCheckBusy=false,v2LastCloudUpdatedAt='';
function v2CloudMarker(){return session?V2_CLOUD_PENDING_KEY+'-'+session.user.id:''}
function v2MergeCloudLedgers(remote,local,preferLocal=true){
  const merged=JSON.parse(JSON.stringify(remote||{})),current=local||{};
  for(const key of ['parties','customers','sales','payments']){
    const combined=new Map();for(const item of Array.isArray(merged[key])?merged[key]:[])combined.set(item.id||JSON.stringify(item),item);
    for(const item of Array.isArray(current[key])?current[key]:[]){const id=item.id||JSON.stringify(item);if(preferLocal||!combined.has(id))combined.set(id,item)}
    merged[key]=[...combined.values()];
  }
  for(const key of ['products','purities','partyPurities']){const seen=new Map();for(const item of [...(merged[key]||[]),...(current[key]||[])])seen.set(String(item).toLowerCase(),item);merged[key]=[...seen.values()]}
  const ratesA=merged.rates||{},ratesB=current.rates||{};merged.rates=Date.parse(ratesB.updatedAt||'')>Date.parse(ratesA.updatedAt||'')?Object.assign({},ratesA,ratesB):Object.assign({},ratesB,ratesA);
  const history=new Map();for(const item of [...(merged.rateHistory||[]),...(current.rateHistory||[])])history.set(item.id||JSON.stringify(item),item);merged.rateHistory=[...history.values()].sort((a,b)=>(b.date+' '+b.time).localeCompare(a.date+' '+a.time)).slice(0,100);
  merged.cloud=Object.assign({},merged.cloud||{},current.cloud||{});return merged;
}
const v2OriginalSave=window.save;
window.save=function(){localStorage.setItem(V2_CLOUD_PENDING_KEY,'1');return v2OriginalSave()};
window.setCloudStatus=function(value){const state=document.getElementById('cloudState');if(state)state.textContent=value;const inline=document.getElementById('cloudInline');if(inline)inline.textContent=value};
function v2HasFocusedEdit(){const el=document.activeElement;return !!(el&&el.closest?.('form')&&!el.closest('#auth')&&/^(INPUT|SELECT|TEXTAREA)$/.test(el.tagName))}
window.pushCloud=async function(){
  if(!session||!client)return;
  if(v2CloudBusy){v2CloudQueuedPush=true;return}
  v2CloudBusy=true;localStorage.setItem(V2_CLOUD_PENDING_KEY,'1');setCloudStatus('Syncing cloud data…');
  try{do{v2CloudQueuedPush=false;let written=false;for(let attempt=0;attempt<5&&!written;attempt++){
      const {data:remote,error:readError}=await client.from('jewellery_ledgers').select('payload,updated_at').eq('user_id',session.user.id).maybeSingle();if(readError)throw readError;
      if(remote?.payload){db=v2MergeCloudLedgers(remote.payload,db,true);ensureExtendedData();localStorage.setItem(dbkey,JSON.stringify(db))}
      const remoteTime=Date.parse(remote?.updated_at||'')||0,updated=new Date(Math.max(Date.now(),remoteTime+1)).toISOString(),payload={user_id:session.user.id,payload:db,updated_at:updated};
      if(remote){let request=client.from('jewellery_ledgers').update({payload:db,updated_at:updated}).eq('user_id',session.user.id);request=remote.updated_at?request.eq('updated_at',remote.updated_at):request.is('updated_at',null);const {data,error}=await request.select('updated_at').maybeSingle();if(error)throw error;if(!data)continue}
      else{const {error}=await client.from('jewellery_ledgers').insert(payload);if(error){if(error.code==='23505')continue;throw error}}
      written=true;v2LastCloudUpdatedAt=updated;
    }if(!written)throw new Error('Cloud ledger changed repeatedly. Tap Sync now to try again.');localStorage.removeItem(V2_CLOUD_PENDING_KEY);localStorage.setItem(v2CloudMarker(),'1');setCloudStatus('Cloud sync · '+session.user.email)}while(v2CloudQueuedPush)}
  catch(error){setCloudStatus('Sync issue · saved on this device');const message=document.getElementById('cloudMsg');if(message)message.textContent='Cloud sync could not finish: '+error.message}
  finally{v2CloudBusy=false}
};
window.pullCloud=async function(){
  if(!session||!client||v2CloudBusy)return;
  v2CloudBusy=true;let needsPush=false;
  try{
    const {data,error}=await client.from('jewellery_ledgers').select('payload,updated_at').eq('user_id',session.user.id).maybeSingle();if(error)throw error;
    if(data?.payload){const pending=localStorage.getItem(V2_CLOUD_PENDING_KEY)==='1';db=v2MergeCloudLedgers(data.payload,db,pending);ensureExtendedData();localStorage.setItem(dbkey,JSON.stringify(db));v2LastCloudUpdatedAt=data.updated_at||'';needsPush=JSON.stringify(db)!==JSON.stringify(data.payload);if(!needsPush){localStorage.removeItem(V2_CLOUD_PENDING_KEY);localStorage.setItem(v2CloudMarker(),'1')}}else needsPush=true;
    setCloudStatus(v2HasFocusedEdit()?'Cloud sync · current entry kept open':'Cloud sync · '+session.user.email);if(!v2HasFocusedEdit())render();
  }catch(error){setCloudStatus('Sync issue · saved on this device');const message=document.getElementById('cloudMsg');if(message)message.textContent='Cloud sync could not finish: '+error.message}
  finally{v2CloudBusy=false}
  if(needsPush||v2CloudQueuedPush)await pushCloud();
};

async function v2CheckCloudForChanges(){if(!session||!client||v2CloudBusy||v2CloudCheckBusy||document.visibilityState!=='visible')return;v2CloudCheckBusy=true;try{if(localStorage.getItem(V2_CLOUD_PENDING_KEY)==='1'){await pullCloud();return}const {data,error}=await client.from('jewellery_ledgers').select('updated_at').eq('user_id',session.user.id).maybeSingle();if(error)throw error;if(data?.updated_at&&(!v2LastCloudUpdatedAt||Date.parse(data.updated_at)>Date.parse(v2LastCloudUpdatedAt))){await pullCloud();return}if(!data)await pushCloud()}catch(error){setCloudStatus('Sync issue · saved on this device')}finally{v2CloudCheckBusy=false}}
window.settingsView=(function(previous){return function(){const html=previous(),end=html.indexOf('</header>');if(end<0)return html;const status=session?'Signed in · '+esc(session.user.email):'Not signed in · data stays on this device';const syncPanel='<section class="panel v2-cloud-guide"><h2>Always sync and merge phone and laptop</h2><p><b>'+status+'</b></p><ol><li>Sign in to the same Goldleaf cloud account with the same email on both devices.</li><li>Phone and laptop records merge automatically on save; the other device refreshes while the app is open.</li><li>Updates are sent immediately when saved. The other active device checks about every 10 seconds; reopen the app to sync when a device was closed.</li></ol><p class="hint">Sync and merge combines records from this device and the cloud. Existing cloud records are kept; no device copy is used to replace the other.</p>'+(session?'':'<button class="primary" type="button" onclick="document.getElementById(\'auth\')?.classList.remove(\'hidden\')">Sign in to cloud</button>')+'</section>';return html.slice(0,end+9)+syncPanel+html.slice(end+9)}})(window.settingsView);
